package com.shortlinkx.controller;
import com.shortlinkx.dto.*;import com.shortlinkx.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/urls") public class UrlController{private final ShortUrlService service;private final AnalyticsService analytics;public UrlController(ShortUrlService service,AnalyticsService analytics){this.service=service;this.analytics=analytics;}@PostMapping public ResponseEntity<CreateUrlResponse> create(@Valid @RequestBody CreateUrlRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping("/{code}/analytics")public AnalyticsResponse analytics(@PathVariable String code){return analytics.get(code);}@GetMapping("/health")public String health(){return"OK";}}
